        return String.valueOf(ch);
    }

    // Check standard unencoded set
    if (UNENCODED_SET.contains(ch)) {
        return String.valueOf(ch);
    }

    byte[] bytes = toUtf8Bytes(String.valueOf(ch));
    StringBuilder sb = new StringBuilder(bytes.length * 3);
    for (byte b : bytes) {
        appendTwoUpperHex(sb.append('%'), b);
    }
    return sb.toString();
}

private static boolean containsCharacter(char ch, char[] immune) {
    for (char ic : immune) {
        if (ic == ch) {
            return true;
        }
    }
    return false;
}
