/**
 * Validates URLs using configurable regular expressions.
 * <p>
 * The original implementation returned a hard‑coded regex when either
 * {@code urlRegexExpression} or {@code urlRegex} was {@code null}.  This
 * caused a denial‑of‑service scenario when a {@code null} value was
 * supplied because the method would attempt to parse a {@code null}
 * expression or return a very large regex that could be expensive to
 * compile.  The updated implementation performs explicit null checks,
 * safely parses the expression, logs any parsing errors, and falls back
 * to a well‑defined default regex.  This guarantees that the method
 * never throws a {@link NullPointerException} and always returns a
 * non‑null, safe regex string.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    /** Default regex used when no custom expression is supplied. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp):\\/\\/" +
            "(([a-z0-9$_\\.\\+!\\*\\'\\(\\),;\\?&=-]|%[0-9a-f]{2})+" +
            "(:([a-z0-9$_\\.\\+!\\*\\'\\(\\),;\\?&=-]|%[0-9a-f]{2})+)?" +
            "@)?(#?)" +
            "((([a-z0-9]\\.|[a-z0-9][a-z0-9-]*[a-z0-9]\\.)*" +
            "[a-z][a-z0-9-]*[a-z0-9]" +
            "|((\\d|[1-9]\\d|1\\d{2}|2[0-4][0-9]|25[0-5])\\.){3}" +
            "(\\d|[1-9]\\d|1\\d{2}|2[0-4][0-9]|25[0-5]))" +
            "(:\\d+)?" +
            "(((\\/\\+([a-z0-9$_\\.\\+!\\*\\'\\(\\),;:@&=-]|%[0-9a-f]{2})*)*" +
            "(\\?([a-z0-9$_\\.\\+!\\*\\'\\(\\),;:@&=-]|%[0-9a-f]{2})*)?)?)?" +
            "(#([a-z0-9$_\\.\\+!\\*\\'\\(\\),;:@&=-]|%[0-9a-f]{2})*)?$";

    private String urlRegex;
    private String urlRegexExpression;

    // other methods

    /**
     * Returns a regular expression used for client‑side URL validation.
     *
     * @return a non‑null regex string
     */
    public String getUrlRegex() {
        // Prefer a user supplied expression if it is non‑blank
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    return (String) parsed;
                }
            } catch (Exception e) {
                LOG.log(Level.WARNING,
                        "Failed to parse urlRegexExpression: {0}", e.getMessage());
                // Fall through to fallback logic
            }
        }

        // Fallback to a simple custom regex if provided
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // Final fallback to the hard‑coded default
        return DEFAULT_URL_REGEX;
    }

    // other methods
}
