import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    /* --------------------------------------------------------------------- */
    /*  Validation utilities                                                 */
    /* --------------------------------------------------------------------- */

    /**
     * A strict whitelist of characters allowed in a media type token.
     * According to RFC 7230 § 3.2.6, a token consists of one or more
     * {@code tchar}s: ALPHA / DIGIT / "!#$%&'*+-.^_`|~".
     *
     * The pattern below matches a non‑empty sequence of these characters.
     * It deliberately excludes all control characters, whitespace,
     * and the slash used to separate major and minor types.
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    /**
     * Validates a media type component (major or subtype).
     *
     * @param str the component to validate
     * @return {@code true} if {@code str} is a valid token or a single '*'
     *         (used for wildcards), {@code false} otherwise
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Allow a single asterisk for wildcard media types
        if ("*".equals(str)) {
            return true;
        }

        // Reject any string containing CR or LF to prevent header injection
        if (str.indexOf('\r') >= 0 || str.indexOf('\n') >= 0) {
            return false;
        }

        // Ensure the string matches the RFC token definition
        return TOKEN_PATTERN.matcher(str).matches();
    }

    /* --------------------------------------------------------------------- */
    /*  Other methods (omitted for brevity)                                  */
    /* --------------------------------------------------------------------- */

}
