    SignedInfo si = sig.getSignedInfo();
    if (si == null) {
        throw new WSSecurityException(...);
    }
    List<Reference> refs = si.getReferences();
    if (refs == null || refs.size() != 1) {
        throw new WSSecurityException(...);
    }
    Reference ref = refs.get(0);
    String uri = ref.getURI();
    if (uri == null || (!uri.isEmpty() && !uri.equals("#" + response.getID()))) {
        throw new WSSecurityException(...);
    }
    // Check canonicalization
    List<Transform> transforms = ref.getTransforms();
    boolean hasC14n = false;
    if (transforms != null) {
        for (Transform t : transforms) {
            if ("http://www.w3.org/2001/10/xml-exc-c14n#".equals(t.getAlgorithm())
                || "http://www.w3.org/TR/2001/REC-xml-c14n-20010315".equals(t.getAlgorithm())) {
                hasC14n = true;
                break;
            }
        }
    }
    if (!hasC14n) {
        throw new WSSecurityException(...);
    }
