    // --------------------------------------------------------------------- //
    // Private helpers
    // --------------------------------------------------------------------- //

    /**
     * Validates that the Response signature references the Response element itself
     * and that the reference uses a standard canonicalisation transform.
     */
    private void validateResponseSignatureCoverage(Response response) throws WSSecurityException {
        Signature sig = response.getSignature();
