        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Remaining part after leading slashes
        String rest = path.substring(i);

        // If nothing remains, the path is either empty or all slashes
        if (rest.isEmpty()) {
            return "/";
        }

        // Prepend a single slash to the remaining path
