import com.opensymphony.xwork2.util.LocalizedTextUtil;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* --------------------------------------------------------------------- */
    /*  Locale validation – only allow standard language[_COUNTRY] patterns   */
    /* --------------------------------------------------------------------- */
    /** 
     * A very small whitelist of acceptable locale strings.
     * Matches patterns such as "en", "en_US", "en-US".
     * Rejects anything containing non‑alphanumeric characters that could
     * be used for XSS or other injection attacks.
     */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2}([_-][a-zA-Z]{2})?$");

    // other methods

    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. Input is validated against a
     * strict whitelist to prevent XSS or malformed locale values.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;

        if (requestedLocale == null) {
            return null;
        }

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            // Reject empty strings early
            if (localeStr.isEmpty()) {
                LOG.warn("Received empty locale string");
                return null;
            }

            // Validate against the whitelist
            if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
                LOG.warn("Invalid locale format received: {}", localeStr);
                return null;
            }

            // Safe to parse now
            locale = LocalizedTextUtil.localeFromString(localeStr, null);
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    // other methods

}
