public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider {

    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and performs a
     * strict authentication check immediately after the TLS handshake.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the user DN or bind name
     * @param credentials        the user password
     * @return an authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                    Object principal,
                                                    Object credentials) throws NamingException {
        if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
            throw new IllegalArgumentException("Unsupported LdapContextFactory type");
        }
        if (!(principal instanceof String) || !(credentials instanceof String)) {
            throw new IllegalArgumentException("Principal and credentials must be Strings");
        }
        String principalStr = ((String) principal).trim();
        String credentialsStr = ((String) credentials).trim();
        if (principalStr.isEmpty() || credentialsStr.isEmpty()) {
            throw new IllegalArgumentException("Principal and credentials must not be empty");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        LdapContext ctx = null;
        try {
            // Create an unauthenticated context
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            if (tls == null) {
                throw new NamingException("STARTTLS negotiation failed: response was null");
            }
            tls.negotiate();

            // Add credentials to the environment and force a bind by performing a trivial lookup
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                    jndiLdapContextFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principalStr);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentialsStr);

