import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Utility class for safely extracting archive entries into a target directory.
 */
public class Expander {

    // other methods

    /**
     * Extracts entries supplied by {@code supplier} into {@code targetDirectory}.
     *
     * <p>This implementation performs rigorous path validation to prevent
     * path‑traversal attacks. Each entry name is resolved against the
     * canonical target directory, normalized, and verified to remain
     * within the target tree. Absolute paths and names containing
     * prohibited components are rejected outright.</p>
     *
     * @param supplier      provides the next readable archive entry
     * @param writer        writes the entry data to an output stream
     * @param targetDirectory the root directory where entries are extracted
     * @throws IOException if extraction fails or a security violation is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject absolute paths or names that start with a separator.
            Path rawEntryPath = Paths.get(entryName);
            if (rawEntryPath.isAbsolute() || entryName.startsWith("/") || entryName.startsWith("\\")) {
                throw new IOException("entry name is absolute or starts with a separator: " + entryName);
            }

            // Resolve and normalize the entry path against the target directory.
            Path resolvedPath = targetDirPath.resolve(rawEntryPath).normalize();

            // Ensure the resolved path is still under the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist.
                if (!Files.isDirectory(resolvedPath)) {
                    Files.createDirectories(resolvedPath);
                }
            } else {
                // Ensure parent directories exist.
                Path parent = resolvedPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
