private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor separately
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Defensive checks for malformed ZIP entries
    if (csize < 0) {
        throw new IOException("Negative entry size encountered: " + csize);
    }
    if (csize == 0) {
        // No data to read – signal EOF immediately
        return -1;
    }

    // If we've already read the declared size, signal EOF
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Ensure we do not attempt to read beyond the declared size
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Refill the internal buffer if needed
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Underlying stream ended before we reached the declared size
            return -1;
        }
        if (l == 0) {
            // Avoid a potential infinite loop on non‑blocking streams
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes to copy to the caller
    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
