import javax.xml.XMLConstants;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.apache.camel.Exchange;
import org.apache.camel.Converter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // --------------------------------------------------------------------
    // Other converter methods
    // --------------------------------------------------------------------

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while
     * protecting against XML External Entity (XXE) attacks.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange used to obtain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be created or configured
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        // Build an InputSource from the StreamSource
        InputSource inputSource = (source.getReader() != null)
                ? new InputSource(source.getReader())
                : new InputSource(source.getInputStream());
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            enableSecureFeatures(sfactory);

            // Create the parser and reader
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disable all external entity handling on the reader
            disableExternalEntityProcessing(xmlReader);

        } catch (Exception e) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", e.toString(), e);
            throw new SAXException("Unable to create a secure XMLReader", e);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    /**
     * Configures a {@link SAXParserFactory} with a set of features that
     * mitigate XXE attacks and other XML-based vulnerabilities.
     */
    private void enableSecureFeatures(SAXParserFactory factory) {
        // Namespace awareness is required for most XML processing
        factory.setNamespaceAware(true);
        // Disable validation – we only need parsing
        factory.setValidating(false);
        // Disable XInclude processing
        factory.setXIncludeAware(false);

        // Secure processing feature
        setFeature(factory, XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Prevent loading of external DTDs and grammars
        setFeature(factory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        setFeature(factory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

        // Disable external entities
        setFeature(factory, "http://xml.org/sax/features/external-general-entities", false);
        setFeature(factory, "http://xml.org/sax/features/external-parameter-entities", false);
    }

    /**
     * Configures an {@link XMLReader} to reject DOCTYPE declarations and
     * external entity references.
     */
    private void disableExternalEntityProcessing(XMLReader reader) {
        // Disallow DOCTYPE declarations entirely
        setFeature(reader, "http://apache.org/xml/features/disallow-doctype-decl", true);

        // Explicitly disable external entities
        setFeature(reader, "http://xml.org/sax/features/external-general-entities", false);
        setFeature(reader, "http://xml.org/sax/features/external-parameter-entities", false);

        // Prevent loading of external DTDs
        setFeature(reader, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
    }

    /**
     * Helper to set a feature on a SAX component, logging a warning if the
     * feature is unsupported.
     */
    private void setFeature(Object component, String name, boolean value) {
        try {
            if (component instanceof SAXParserFactory) {
                ((SAXParserFactory) component).setFeature(name, value);
            } else if (component instanceof XMLReader) {
                ((XMLReader) component).setFeature(name, value);
            }
        } catch (Exception e) {
            LOG.warn("Feature {}={} is not supported: {}", name, value, e.toString());
        }
    }

    // --------------------------------------------------------------------
    // Other converter methods
    // --------------------------------------------------------------------
}
